function validate(input) {
  const [{ Users = [], Orders = [], Items = [] }] = input;
  const sellers = new Set(), items = new Set(), orders = new Set();
  for (const [id, joined, brand] of Users) {
    if (id === null || joined === null || brand === null) return 'Users rows cannot hold nulls.';
    if (sellers.has(id)) return `seller_id ${id} appears twice in Users.`;
    sellers.add(id);
  }
  for (const [id, brand] of Items) {
    if (id === null || brand === null) return 'Items rows cannot hold nulls.';
    if (items.has(id)) return `item_id ${id} appears twice in Items.`;
    items.add(id);
  }
  for (const [id, date, item, seller] of Orders) {
    if (id === null || date === null) return 'Orders rows need an order_id and an order_date.';
    if (orders.has(id)) return `order_id ${id} appears twice in Orders.`;
    orders.add(id);
    if (!items.has(item)) return `Order ${id} names item ${item}, which is not in Items.`;
    if (!sellers.has(seller)) return `Order ${id} names seller ${seller}, who is not in Users.`;
  }
  return null;
}

