function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const brands = ['Lenovo', 'Samsung', 'LG', 'HP'];
  const favorites = ['Lenovo', 'Samsung', 'LG', 'HP', 'Apple'];
  const day = (month, last) => `2019-${String(month).padStart(2, '0')}-${String(1 + Math.floor(rand() * last)).padStart(2, '0')}`;
  const small = size === 'small';
  const userCount = small ? Math.floor(rand() * 6) : 300;
  const itemCount = small ? Math.floor(rand() * 6) : 400;
  const orderCount = small ? Math.floor(rand() * 9) : 1800;
  // Small cases use scattered ids so the output order is tested; large ones use 1..n.
  const ids = n => {
    const pool = Array.from({ length: small ? 9 : n }, (_, i) => i + 1);
    for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
    return pool.slice(0, n);
  };
  const Users = ids(userCount).map(id => [id, day(1 + Math.floor(rand() * 2), 28), pick(favorites)]);
  const Items = ids(itemCount).map(id => [id, pick(brands)]);
  const Orders = [];
  if (Users.length && Items.length) {
    for (let i = 1; i <= orderCount; i++) Orders.push([i, day(8, 28), pick(Items)[0], pick(Users)[0]]);
  }
  return [{ Users, Orders, Items }];
}
